cells=[
{"cell_type":"markdown","metadata":{},"source":["# Raw column-profile distribution analysis\n\nThis notebook summarizes raw profiles before cleaning without storing trajectory arrays in a DataFrame. It processes one CSV at a time and does not modify profiles."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["from pathlib import Path\nimport re, gc\nfrom collections import defaultdict\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nRESULTS_ROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_analysis')\nQC_ROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_quality_qc')\nQC_ROOT.mkdir(parents=True,exist_ok=True)\npattern=re.compile(r'^(D\\d+)_(lh|rh)_(.+)_(md|fa|ad|rd)\\.csv$')\nDEPTHS=21\nprint('Reading:',RESULTS_ROOT)"]},
{"cell_type":"markdown","metadata":{},"source":["## 1. Online bad-point aggregation\n\nEach file is loaded once, summarized, and released. Only compact counters are retained."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["summary=[]; categories=defaultdict(int); depths=defaultdict(int); type_counts=defaultdict(int); overlap=defaultdict(lambda:[0,0,0])\nfor folder in sorted(RESULTS_ROOT.glob('D*/profiles_before_clean')):\n  for path in sorted(folder.glob('*.csv')):\n    m=pattern.match(path.name)\n    if not m: continue\n    subject,hemi,region,metric=m.groups()\n    if path.stat().st_size==0:\n      summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'empty','total_columns':0,'bad_points':0,'bad_columns':0,'one_bad_point':0,'two_bad_points':0,'three_or_more_bad_points':0,'consecutive_columns':0}); continue\n    try: a=np.loadtxt(path,delimiter=',',ndmin=2)\n    except Exception as e:\n      summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'unreadable','total_columns':0,'bad_points':0,'bad_columns':0,'one_bad_point':0,'two_bad_points':0,'three_or_more_bad_points':0,'consecutive_columns':0,'error':str(e)}); continue\n    if a.shape[1]!=DEPTHS: del a; gc.collect(); continue\n    finite=np.isfinite(a); bad=(~finite)|(a==0); counts=bad.sum(axis=1)\n    for n in counts: categories[(subject,metric,'1' if n==1 else '2' if n==2 else '3_or_more' if n>=3 else '0')]+=1\n    for d,n in enumerate(bad.sum(axis=0)):\n      if n: depths[(metric,d)]+=int(n)\n    type_counts[(metric,'exact_zero')]+=int((a==0).sum()); type_counts[(metric,'nan')]+=int(np.isnan(a).sum()); type_counts[(metric,'inf')]+=int(np.isinf(a).sum())\n    consecutive=int(np.sum(np.any(bad[:,1:]&bad[:,:-1],axis=1))) if a.shape[1]>1 else 0\n    summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'valid','total_columns':a.shape[0],'bad_points':int(bad.sum()),'bad_columns':int(np.any(bad,axis=1).sum()),'one_bad_point':int((counts==1).sum()),'two_bad_points':int((counts==2).sum()),'three_or_more_bad_points':int((counts>=3).sum()),'consecutive_columns':consecutive})\n    del a,finite,bad,counts; gc.collect()\nfile_summary=pd.DataFrame(summary); file_summary['bad_point_pct']=100*file_summary.bad_points/file_summary.total_columns.replace(0,np.nan)/DEPTHS\nfile_summary.to_csv(QC_ROOT/'file_badpoint_summary.csv',index=False)\ncategory_summary=pd.DataFrame([{'subject':k[0],'metric':k[1],'category':k[2],'column_count':v} for k,v in categories.items()]); category_summary.to_csv(QC_ROOT/'bad_points_per_column_summary.csv',index=False)\ndepth_summary=pd.DataFrame([{'metric':k[0],'depth':k[1],'bad_point_count':v} for k,v in depths.items()]); depth_summary.to_csv(QC_ROOT/'depth_bad_point_summary.csv',index=False)\ntype_summary=pd.DataFrame([{'metric':k[0],'type':k[1],'count':v} for k,v in type_counts.items()]); type_summary.to_csv(QC_ROOT/'bad_point_type_summary.csv',index=False)\ndisplay(file_summary.head()); display(type_summary)"]},
{"cell_type":"markdown","metadata":{},"source":["## 2. Subject and population summaries\n\nThese are the compact tables used for population-level QC."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["subject_summary=file_summary.groupby('subject',as_index=False).agg(total_columns=('total_columns','sum'),bad_points=('bad_points','sum'),bad_columns=('bad_columns','sum'),one_bad_point=('one_bad_point','sum'),two_bad_points=('two_bad_points','sum'),three_or_more_bad_points=('three_or_more_bad_points','sum'),empty_files=('status',lambda s:int((s=='empty').sum())))\nsubject_summary['bad_point_pct']=100*subject_summary.bad_points/(subject_summary.total_columns*DEPTHS).replace(0,np.nan)\nsubject_summary.to_csv(QC_ROOT/'subject_badpoint_summary.csv',index=False)\nregion_summary=file_summary.groupby(['subject','hemisphere','region','metric'],as_index=False).agg(total_columns=('total_columns','sum'),bad_points=('bad_points','sum'),bad_columns=('bad_columns','sum'),one_bad_point=('one_bad_point','sum'),two_bad_points=('two_bad_points','sum'),three_or_more_bad_points=('three_or_more_bad_points','sum'),consecutive_columns=('consecutive_columns','sum'))\nregion_summary.to_csv(QC_ROOT/'subject_hemisphere_region_metric_summary.csv',index=False)\ndisplay(subject_summary); display(region_summary.head())"]},
{"cell_type":"markdown","metadata":{},"source":["## 3. Population visualizations"]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["fig,axes=plt.subplots(1,2,figsize=(14,5))\nsubject_summary.sort_values('subject').plot(x='subject',y='bad_point_pct',kind='bar',ax=axes[0],legend=False); axes[0].set_title('Bad-point percentage by subject'); axes[0].set_ylabel('%'); axes[0].tick_params(axis='x',rotation=90)\nif not depth_summary.empty:\n  for metric,g in depth_summary.groupby('metric'): axes[1].plot(g.depth,g.bad_point_count,marker='o',label=metric.upper())\naxes[1].set_title('Bad-point distribution by depth'); axes[1].set_xlabel('Depth'); axes[1].set_ylabel('Count'); axes[1].legend(); axes[1].grid(alpha=.25)\nfig.tight_layout(); fig.savefig(QC_ROOT/'population_badpoint_overview.png',dpi=180); display(fig)"]}
]
cells[3]["source"]=["from collections import defaultdict\n\n# Reuse cached summaries when all expected files exist. Set RECOMPUTE=True only when new profiles arrive.\nRECOMPUTE=False\nexpected=[QC_ROOT/'file_badpoint_summary.csv',QC_ROOT/'bad_points_per_column_summary.csv',QC_ROOT/'depth_bad_point_summary.csv',QC_ROOT/'bad_point_type_summary.csv']\nif not RECOMPUTE and all(p.is_file() for p in expected):\n    file_summary=pd.read_csv(QC_ROOT/'file_badpoint_summary.csv')\n    category_summary=pd.read_csv(QC_ROOT/'bad_points_per_column_summary.csv')\n    depth_summary=pd.read_csv(QC_ROOT/'depth_bad_point_summary.csv')\n    type_summary=pd.read_csv(QC_ROOT/'bad_point_type_summary.csv')\n    print('Loaded cached summaries; profile files were not reread.')\nelse:\n    summary=[]; categories=defaultdict(int); depths=defaultdict(int); type_counts=defaultdict(int)\n    for folder in sorted(RESULTS_ROOT.glob('D*/profiles_before_clean')):\n      for path in sorted(folder.glob('*.csv')):\n        m=pattern.match(path.name)\n        if not m: continue\n        subject,hemi,region,metric=m.groups()\n        if path.stat().st_size==0:\n          summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'empty','total_columns':0,'bad_points':0,'bad_columns':0,'one_bad_point':0,'two_bad_points':0,'three_or_more_bad_points':0,'consecutive_columns':0}); continue\n        try: a=np.loadtxt(path,delimiter=',',ndmin=2)\n        except Exception as e: summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'unreadable','total_columns':0,'bad_points':0,'bad_columns':0,'one_bad_point':0,'two_bad_points':0,'three_or_more_bad_points':0,'consecutive_columns':0,'error':str(e)}); continue\n        if a.shape[1]!=DEPTHS: del a; continue\n        finite=np.isfinite(a); bad=(~finite)|(a==0); counts=bad.sum(axis=1)\n        for n in counts: categories[(subject,metric,'1' if n==1 else '2' if n==2 else '3_or_more' if n>=3 else '0')]+=1\n        for d,n in enumerate(bad.sum(axis=0)):\n          if n: depths[(metric,d)]+=int(n)\n        type_counts[(metric,'exact_zero')]+=int((a==0).sum()); type_counts[(metric,'nan')]+=int(np.isnan(a).sum()); type_counts[(metric,'inf')]+=int(np.isinf(a).sum())\n        consecutive=int(np.sum(np.any(bad[:,1:]&bad[:,:-1],axis=1))) if a.shape[1]>1 else 0\n        summary.append({'subject':subject,'hemisphere':hemi,'region':region,'metric':metric,'status':'valid','total_columns':a.shape[0],'bad_points':int(bad.sum()),'bad_columns':int(np.any(bad,axis=1).sum()),'one_bad_point':int((counts==1).sum()),'two_bad_points':int((counts==2).sum()),'three_or_more_bad_points':int((counts>=3).sum()),'consecutive_columns':consecutive})\n        del a,finite,bad,counts; gc.collect()\n    file_summary=pd.DataFrame(summary); file_summary['bad_point_pct']=100*file_summary.bad_points/file_summary.total_columns.replace(0,np.nan)/DEPTHS\n    file_summary.to_csv(QC_ROOT/'file_badpoint_summary.csv',index=False)\n    category_summary=pd.DataFrame([{'subject':k[0],'metric':k[1],'category':k[2],'column_count':v} for k,v in categories.items()]); category_summary.to_csv(QC_ROOT/'bad_points_per_column_summary.csv',index=False)\n    depth_summary=pd.DataFrame([{'metric':k[0],'depth':k[1],'bad_point_count':v} for k,v in depths.items()]); depth_summary.to_csv(QC_ROOT/'depth_bad_point_summary.csv',index=False)\n    type_summary=pd.DataFrame([{'metric':k[0],'type':k[1],'count':v} for k,v in type_counts.items()]); type_summary.to_csv(QC_ROOT/'bad_point_type_summary.csv',index=False)\ndisplay(file_summary.head()); display(type_summary)"]
cells[6]["source"]=["plt.close('all')\nsubject_summary=pd.read_csv(QC_ROOT/'subject_badpoint_summary.csv') if (QC_ROOT/'subject_badpoint_summary.csv').is_file() else file_summary.groupby('subject',as_index=False).agg(total_columns=('total_columns','sum'),bad_points=('bad_points','sum'),bad_columns=('bad_columns','sum'),one_bad_point=('one_bad_point','sum'),two_bad_points=('two_bad_points','sum'),three_or_more_bad_points=('three_or_more_bad_points','sum'),empty_files=('status',lambda s:int((s=='empty').sum())))\nif 'bad_point_pct' not in subject_summary: subject_summary['bad_point_pct']=100*subject_summary.bad_points/(subject_summary.total_columns*DEPTHS).replace(0,np.nan)\nfig,axes=plt.subplots(1,3,figsize=(19,5))\nsubject_summary.sort_values('subject').plot(x='subject',y='bad_point_pct',kind='bar',ax=axes[0],legend=False); axes[0].set_title('Bad-point percentage by subject'); axes[0].set_ylabel('%'); axes[0].set_xlabel('Subject (labels hidden)'); axes[0].set_xticks([])\ntop=subject_summary.sort_values('bad_point_pct',ascending=False).head(20).sort_values('bad_point_pct')\naxes[1].barh(top.subject,top.bad_point_pct); axes[1].set_title('Top 20 subjects by bad-point percentage'); axes[1].set_xlabel('Bad points (%)'); axes[1].grid(axis='x',alpha=.25)\nif not depth_summary.empty:\n  for metric,g in depth_summary.groupby('metric'):\n    g=g.sort_values('depth')\n    axes[2].plot(g.depth,g.bad_point_count,marker='o',label=metric.upper())\naxes[2].set_title('Bad-point distribution by depth'); axes[2].set_xlabel('Depth'); axes[2].set_ylabel('Count'); axes[2].legend(); axes[2].grid(alpha=.25)\nfig.tight_layout(); fig.savefig(QC_ROOT/'population_badpoint_overview.png',dpi=180); display(fig)"]
