cells[7]["source"]=["from IPython.display import Image, display\nimport matplotlib.pyplot as plt\nplt.close('all')\nsubject_summary=pd.read_csv(QC_ROOT/'subject_badpoint_summary.csv')\ndepth_summary=pd.read_csv(QC_ROOT/'depth_badpoint_summary.csv')\nfig,axes=plt.subplots(1,3,figsize=(19,5))\nall_subjects=subject_summary.sort_values('subject')\nall_subjects.plot(x='subject',y='bad_point_pct',kind='bar',ax=axes[0],legend=False); axes[0].set_title('Bad-point percentage by subject'); axes[0].set_ylabel('%'); axes[0].set_xlabel('Subject (labels hidden)'); axes[0].set_xticks([])\ntop=subject_summary.nlargest(20,'bad_point_pct').sort_values('bad_point_pct')\naxes[1].barh(top.subject,top.bad_point_pct); axes[1].set_title('Top 20 subjects by bad-point percentage'); axes[1].set_xlabel('Bad points (%)'); axes[1].grid(axis='x',alpha=.25)\nfor metric,g in depth_summary.groupby('metric'):\n  g=g.sort_values('depth'); axes[2].plot(g.depth,g.bad_point_count,marker='o',label=metric.upper())\naxes[2].set_title('Bad-point distribution by depth'); axes[2].set_xlabel('Depth'); axes[2].set_ylabel('Count'); axes[2].legend(); axes[2].grid(alpha=.25)\nfig.tight_layout(); out=QC_ROOT/'population_badpoint_overview.png'; fig.savefig(out,dpi=180); plt.close(fig); display(Image(filename=str(out)))"]
